mapper.sql:
with contract as ( select contract_code, client_code, client_name, org_id, tax_rate, financial_contract_status, contract_status from eg_contract ec where 1=1
and ec.org_id in
#{item}
and ec.contract_code in
#{item}
) , contract_balance as ( select contract_code, org_id,
sum(${item}) ${item}
, sum(unrealized_revenue_balance) unrealized_revenue_balance_sum
from eg_contract_balance ecb where 1=1
and ecb.org_id in
#{item}
and ecb.contract_code in
#{item}
and ecb.id in( select tmp.id from eg_contract_balance tmp where 1=1
and tmp.period_code <= #{param.periodCode}
and tmp.org_id in
#{item}
and tmp.contract_code in
#{item}
and tmp.voucher_id in ( select max(id) from eg_contract_balance where 1=1
and org_id in
#{item}
and voucher_date <= #{param.queryDate}
and contract_code in
#{item}
group by org_id, contract_code )) group by org_id, contract_code ) , res as ( select contract.*, 0 as ta_amount, 0 as non_invoiced_profit, 0 as non_received_principal, 0 as non_received_profit,
contract_balance.${item}
, coalesce(esfd.accumulated_accrued_amount,0) unrealized_revenue_balance_no_service_fee , coalesce(contract_balance.unrealized_revenue_balance_sum,0) - coalesce(esfd.accumulated_accrued_amount,0) unrealized_revenue_balance_service_fee
from contract left join contract_balance on contract.contract_code = contract_balance.contract_code and contract.org_id = contract_balance.org_id left join eg_service_fee_details esfd on contract.contract_code = esfd.contract_code and contract.org_id = esfd.org_id )

mapper.select:
select org_id , contract_code , account_code ,
       sum(month_debit_amount) month_debit_amount, sum(month_credit_amount) month_credit_amount,
       sum(month_end_debit_balance) month_end_debit_balance, sum(month_end_credit_balance) month_end_credit_balance
from eg_account_assist_balance eaab where 1=1

    and org_id in

        #{item}




    and currency_code = #{param.currencyCode}


    and period_code = #{param.periodCode}


    and contract_code in

        #{item}



    and account_code in

        #{item}


group by org_id , contract_code , account_code

with contract as ( select ec.contract_code, ec.client_code, ec.client_name, ec.org_id, ec.tax_rate, ec.financial_contract_status, ec.contract_status from eg_contract ec where 1=1 and ec.contract_code_m is null
and ec.org_id in
#{item}
and ec.contract_code in
#{item}
) , contract_balance as ( select ecb.contract_code, ecb.org_id,
sum(${item}) ${item}
, sum(unrealized_revenue_balance) unrealized_revenue_balance_sum from eg_contract_balance ecb where 1=1
and ecb.org_id in
#{item}
and ecb.contract_code in
#{item}
and ecb.id in( select max(tmp.id) from eg_contract_balance tmp where 1=1
and tmp.period_code <= #{param.periodCode}
and TO_CHAR(tmp.voucher_date,'YYYY-MM-DD') <= #{param.queryDate}
and tmp.org_id in
#{item}
and tmp.contract_code in
#{item}
group by tmp.org_id, tmp.contract_code, tmp.client_code, tmp.bill_contract_code ) group by ecb.contract_code, ecb.org_id ) , res as ( select coalesce(contract.contract_code, '') contract_code, coalesce(contract.client_code, '') client_code, coalesce(contract.client_name, '') client_name, coalesce(contract.org_id, '') org_id, coalesce(contract.tax_rate, null) tax_rate, coalesce(contract.financial_contract_status, '') financial_contract_status, coalesce(contract.contract_status, '') contract_status, coalesce(( select sum(coalesce(t.ta_amount, 0)) from eg_contract_ta_amount t where t.contract_code = contract.contract_code and t.transaction_date <= #{param.queryDate}), 0) as ta_amount, coalesce(( select sum(coalesce(t1.actual_repayment_interes_amount, 0)) from eg_repayment_plan_exceldata t1 where t1.plan_date <= #{param.queryDate} and t1.contract_code = contract.contract_code)-( select sum(coalesce(t2.tax_amount, 0)) from eg_invoice_claim t2 where t2.document_date <= #{param.queryDate} and t2.contract_code = contract.contract_code), 0) as non_invoiced_profit, coalesce(( select sum(coalesce(t.principal_amount, 0)) from eg_repayment_plan t where t.contract_code = contract.contract_code and t.plan_date <= #{param.queryDate}) - ( select sum(coalesce(t1.actual_repayment_principal_amount, 0)) from eg_repayment_plan_exceldata t1 where t1.plan_date <= #{param.queryDate} and t1.contract_code = contract.contract_code), 0) as non_received_principal, coalesce(( select sum(coalesce(t.interest_amount, 0)) from eg_repayment_plan t where t.contract_code = contract.contract_code and t.plan_date <= #{param.queryDate}) - ( select sum(coalesce(t1.actual_repayment_interes_amount, 0)) from eg_repayment_plan_exceldata t1 where t1.plan_date <= #{param.queryDate} and t1.contract_code = contract.contract_code), 0) as non_received_profit,
contract_balance.${item}
, coalesce(esfd.accumulated_accrued_amount,0) unrealized_revenue_balance_no_service_fee , coalesce(contract_balance.unrealized_revenue_balance_sum,0) - coalesce(esfd.accumulated_accrued_amount,0) unrealized_revenue_balance_service_fee from contract left join contract_balance on contract.contract_code = contract_balance.contract_code and contract.org_id = contract_balance.org_id left join eg_service_fee_details esfd on contract.contract_code = esfd.contract_code and contract.org_id = esfd.org_id ) select * from res order by res.contract_code,res.client_code
